import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import theme from 'app/theme';
import { ZimmButton } from './index';

// ZimmIcon has a known Vitest breakage — SVG imports resolve to raw path strings in this
// environment, causing a top-level side effect on the SFCC icons barrel to throw. Mock it
// at the module level so any story/test that renders an icon-consuming ZimmButton variant
// doesn't require changes to Tier 1 test config (vitest.config.*). See testing.md Known gap.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

const renderButton = (props: React.ComponentProps<typeof ZimmButton>) =>
  render(
    <ChakraProvider theme={theme}>
      <ZimmButton {...props} />
    </ChakraProvider>,
  );

describe('ZimmButton', () => {
  test('calls onClick when the button is clicked and ariaDisabled is not set', () => {
    const onClick = vi.fn();
    renderButton({ label: 'Save', onClick });

    fireEvent.click(screen.getByRole('button', { name: 'Save' }));

    expect(onClick).toHaveBeenCalledTimes(1);
  });

  test('does not call onClick when ariaDisabled is true — handler is suppressed at the React layer', () => {
    // The component sets handleClick = ariaDisabled ? undefined : onClick so the DOM click
    // propagates (keeping the button focusable and tab-reachable) but the React handler is never
    // invoked — see ZimmButton JSDoc on ariaDisabled.
    const onClick = vi.fn();
    renderButton({ label: 'Save', onClick, ariaDisabled: true });

    fireEvent.click(screen.getByRole('button', { name: 'Save' }));

    expect(onClick).not.toHaveBeenCalled();
  });

  test('sets aria-disabled="true" on the rendered button when ariaDisabled is true', () => {
    renderButton({ label: 'Save', ariaDisabled: true });

    expect(screen.getByRole('button', { name: 'Save' })).toHaveAttribute('aria-disabled', 'true');
  });

  test('omits the aria-disabled attribute entirely when ariaDisabled is false', () => {
    // ariaDisabledAttr = ariaDisabled || undefined — false evaluates to undefined, so no attribute.
    renderButton({ label: 'Save', ariaDisabled: false });

    expect(screen.getByRole('button', { name: 'Save' })).not.toHaveAttribute('aria-disabled');
  });

  test('overrides type to "button" when ariaDisabled is true, even when type="submit" is passed', () => {
    // Prevents an ariaDisabled button from accidentally submitting a form — the component
    // renders type={ariaDisabled ? 'button' : type} on ChakraButton.
    renderButton({ label: 'Save', type: 'submit', ariaDisabled: true });

    expect(screen.getByRole('button', { name: 'Save' })).toHaveAttribute('type', 'button');
  });

  test('preserves type="submit" when ariaDisabled is false', () => {
    renderButton({ label: 'Save', type: 'submit' });

    expect(screen.getByRole('button', { name: 'Save' })).toHaveAttribute('type', 'submit');
  });
});

describe('ZimmButton — variant="social" (ZimmSocialButton consolidation)', () => {
  test('renders the icon passed via the icon prop', () => {
    renderButton({ variant: 'social', label: 'Sign in with Google', icon: <span>icon</span> });

    expect(screen.getByRole('button', { name: 'Sign in with Google' })).toHaveTextContent('icon');
  });

  test('renders the visible label text inside the button', () => {
    renderButton({ variant: 'social', label: 'Sign in with Google', icon: <span>icon</span> });

    expect(screen.getByText('Sign in with Google')).toBeInTheDocument();
  });

  test('icon box defaults to md (16px) when iconSize is not given', () => {
    const { container } = renderButton({ variant: 'social', label: 'Sign in with Apple', icon: <span /> });

    const iconBox = container.querySelector('span[aria-hidden="true"]');
    expect(iconBox).toHaveStyle({ width: 'var(--zimm-icon-size-md)', height: 'var(--zimm-icon-size-md)' });
  });

  test('iconSize picks a different registered box size', () => {
    const { container } = renderButton({
      variant: 'social',
      label: 'Sign in with Apple',
      icon: <span />,
      iconSize: 'lg',
    });

    const iconBox = container.querySelector('span[aria-hidden="true"]');
    expect(iconBox).toHaveStyle({ width: 'var(--zimm-icon-size-lg)', height: 'var(--zimm-icon-size-lg)' });
  });

  test('iconSx overrides the box size for a one-off value outside the four registered sizes', () => {
    const { container } = renderButton({
      variant: 'social',
      label: 'Sign in with Apple',
      icon: <span />,
      iconSx: { width: '18px', height: '18px' },
    });

    const iconBox = container.querySelector('span[aria-hidden="true"]');
    expect(iconBox).toHaveStyle({ width: '18px', height: '18px' });
  });

  test('defaults to full width when no fullWidth is given', () => {
    renderButton({ variant: 'social', label: 'Sign in with Apple', icon: <span /> });

    expect(screen.getByRole('button', { name: 'Sign in with Apple' })).toHaveStyle({ width: '100%' });
  });

  test('an explicit fullWidth={false} overrides the social default', () => {
    renderButton({ variant: 'social', label: 'Sign in with Apple', icon: <span />, fullWidth: false });

    expect(screen.getByRole('button', { name: 'Sign in with Apple' })).not.toHaveStyle({ width: '100%' });
  });

  test('a non-social variant is not full width by default', () => {
    renderButton({ label: 'Save' });

    expect(screen.getByRole('button', { name: 'Save' })).not.toHaveStyle({ width: '100%' });
  });

  test('a non-social variant still honours an explicit fullWidth={true}', () => {
    renderButton({ label: 'Save', fullWidth: true });

    expect(screen.getByRole('button', { name: 'Save' })).toHaveStyle({ width: '100%' });
  });
});

