import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { ZimmSizeSelector } from './index';
import { useZimmSizeSelector } from 'app/hooks/useZimmSizeSelector';

// ZimmIcon imports the base SFCC icons barrel which throws under Vitest (SVG imports resolve
// to raw path strings, not components). No assertion below depends on icon content.
// See footerNavColumn/index.test.tsx and zimmSubscribeSection/index.test.tsx for the same pattern.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: () => null,
}));

// ZimmDropdown's open/close mechanics, keyboard navigation, and chevron icon are already
// covered by its own stories. Stubbing it here scopes this suite to ZimmSizeSelector's
// own render-branch / event-wiring contract, not a second copy of that coverage.
// The stub calls renderItems immediately so item click handlers remain reachable in tests.
vi.mock('app/components/ui-kits/atoms/zimmDropdown', () => ({
  ZimmDropdown: ({
    renderItems,
    hasError,
    errorMessage,
    id,
  }: {
    renderItems?: (state: {
      focusedIndex: null;
      close: () => void;
      triggerId: string;
      panelId: string;
    }) => React.ReactNode;
    hasError?: boolean;
    errorMessage?: string;
    id?: string;
  }) => (
    <div data-testid="zimm-dropdown" data-has-error={String(Boolean(hasError))}>
      {hasError && errorMessage && <p role="alert">{errorMessage}</p>}
      {renderItems?.({
        focusedIndex: null,
        close: vi.fn(),
        triggerId: `${id}-trigger`,
        panelId: `${id}-panel`,
      })}
    </div>
  ),
  getDropdownOptionId: (panelId: string, index: number) => `${panelId}-option-${index}`,
}));

// ZimmDropdownItem's own styling and focus-ring contract are covered by its own stories.
// A minimal stub that renders a queryable option element is sufficient here.
vi.mock('app/components/ui-kits/atoms/zimmDropdownItem', () => ({
  ZimmDropdownItem: ({
    zimmSize,
    onClick,
    isSelected,
    status,
  }: {
    zimmSize: string;
    onClick?: () => void;
    isSelected?: boolean;
    status?: string;
  }) => (
    <li role="option" aria-selected={isSelected} data-status={status} onClick={onClick} onKeyDown={() => {}}>
      {zimmSize}
    </li>
  ),
}));

// ZimmNavItem is rendered inside the panel and trigger row. Its own behaviour is covered
// elsewhere; stubbing it prevents transitive ZimmIcon SVG issues in Vitest.
vi.mock('app/components/ui-kits/atoms/zimmNavItem', () => ({
  ZimmNavItem: ({ label, onClick }: { label: string; onClick?: () => void }) => (
    <button onClick={onClick}>{label}</button>
  ),
}));

// useZimmSizeSelector's state machine (selection, error transitions, OOS-aware keyboard nav)
// is covered by a dedicated hook test. Mocking it here isolates this suite to
// ZimmSizeSelector's own contract: render-branch decisions and event-wiring.
vi.mock('app/hooks/useZimmSizeSelector', () => ({
  useZimmSizeSelector: vi.fn(),
  // deriveSizeStatus is called inline inside ZimmSizeSelector's renderItems — pass through a
  // functionally equivalent version so status props on the stub items are realistic.
  deriveSizeStatus: ({ orderable }: { orderable: boolean }, isBackorderable = false): string => {
    if (!orderable) return isBackorderable ? 'notify-me' : 'out-of-stock';
    return 'in-stock';
  },
}));

// Mock useBreakpointValue so it returns a stable value (desktop = false) without needing a
// full Chakra responsive context. Pass everything else through so ChakraProvider still works.
vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useBreakpointValue: vi.fn().mockReturnValue(false),
  };
});

// ---- typed mock ref ----

const mockUseZimmSizeSelector = vi.mocked(useZimmSizeSelector);

// ---- factory helpers ----

type SizeValue = { value: string; name: string; orderable: boolean };

/** Builds a variationAttribute prop with sensible defaults. */
function buildVariationAttribute(
  values: SizeValue[] = [
    { value: 's', name: 'S', orderable: true },
    { value: 'm', name: 'M', orderable: true },
    { value: 'l', name: 'L', orderable: true },
  ],
) {
  return { id: 'size', name: 'Size', values };
}

/** Builds a full useZimmSizeSelector return value with vi.fn() stubs. */
function buildHookReturn(
  overrides: Partial<ReturnType<typeof useZimmSizeSelector>> = {},
): ReturnType<typeof useZimmSizeSelector> {
  return {
    selectedValue: null,
    hasError: false,
    select: vi.fn(),
    setError: vi.fn(),
    clearError: vi.fn(),
    findNextOrderableIndex: vi.fn().mockReturnValue(null),
    ...overrides,
  };
}

/** Wraps renders in ChakraProvider + IntlProvider — useIntl is called unconditionally and throws without one. */
const Wrapper = ({ children }: { children: React.ReactNode }) => (
  <IntlProvider locale="en">
    <ChakraProvider>{children}</ChakraProvider>
  </IntlProvider>
);

// ---- tests ----

describe('ZimmSizeSelector', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockUseZimmSizeSelector.mockReturnValue(buildHookReturn());
  });

  describe('isOneSize branch (single variation value)', () => {
    test('renders a role="status" paragraph with "One size" text', () => {
      const singleValue: SizeValue[] = [{ value: 'os', name: 'One Size', orderable: true }];

      render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute(singleValue)}
          selectedValue={null}
          onSelectionChange={vi.fn()}
        />,
        { wrapper: Wrapper },
      );

      expect(screen.getByRole('status')).toHaveTextContent('One size');
    });

    test('does not render ZimmDropdown when there is exactly one size value', () => {
      const singleValue: SizeValue[] = [{ value: 'os', name: 'One Size', orderable: true }];

      render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute(singleValue)}
          selectedValue={null}
          onSelectionChange={vi.fn()}
        />,
        { wrapper: Wrapper },
      );

      expect(screen.queryByTestId('zimm-dropdown')).not.toBeInTheDocument();
    });
  });

  describe('showError prop → hook error state bridge', () => {
    test('calls setError when showError transitions from false to true', () => {
      const setError = vi.fn();
      const clearError = vi.fn();
      mockUseZimmSizeSelector.mockReturnValue(buildHookReturn({ setError, clearError }));

      const { rerender } = render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute()}
          selectedValue={null}
          onSelectionChange={vi.fn()}
          showError={false}
        />,
        { wrapper: Wrapper },
      );

      // Mounting with showError=false should not call setError.
      expect(setError).not.toHaveBeenCalled();

      rerender(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute()}
          selectedValue={null}
          onSelectionChange={vi.fn()}
          showError={true}
        />,
      );

      expect(setError).toHaveBeenCalledTimes(1);
    });

    test('calls clearError when showError transitions back to false', () => {
      const setError = vi.fn();
      const clearError = vi.fn();
      mockUseZimmSizeSelector.mockReturnValue(buildHookReturn({ setError, clearError }));

      // Mounting with showError=true triggers setError; clearError should not fire yet.
      const { rerender } = render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute()}
          selectedValue={null}
          onSelectionChange={vi.fn()}
          showError={true}
        />,
        { wrapper: Wrapper },
      );

      expect(clearError).not.toHaveBeenCalled();

      rerender(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute()}
          selectedValue={null}
          onSelectionChange={vi.fn()}
          showError={false}
        />,
      );

      expect(clearError).toHaveBeenCalled();
    });
  });

  describe('auto-selection on mount for one-size products', () => {
    test('calls onSelectionChange with the single value on mount when not already selected', () => {
      const onSelectionChange = vi.fn();
      const singleValue: SizeValue[] = [{ value: 'os', name: 'One Size', orderable: true }];

      render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute(singleValue)}
          selectedValue={null}
          onSelectionChange={onSelectionChange}
        />,
        { wrapper: Wrapper },
      );

      expect(onSelectionChange).toHaveBeenCalledWith('os');
    });

    test('does not call onSelectionChange when the single value is already the selectedValue', () => {
      const onSelectionChange = vi.fn();
      const singleValue: SizeValue[] = [{ value: 'os', name: 'One Size', orderable: true }];

      render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute(singleValue)}
          selectedValue="os"
          onSelectionChange={onSelectionChange}
        />,
        { wrapper: Wrapper },
      );

      expect(onSelectionChange).not.toHaveBeenCalled();
    });
  });

  describe('handleItemSelect — item click event wiring', () => {
    test('calls onSelectionChange with the value of the clicked size item', async () => {
      const onSelectionChange = vi.fn();
      const values: SizeValue[] = [
        { value: 's', name: 'S', orderable: true },
        { value: 'm', name: 'M', orderable: true },
      ];

      render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute(values)}
          selectedValue={null}
          onSelectionChange={onSelectionChange}
        />,
        { wrapper: Wrapper },
      );

      await userEvent.click(screen.getByRole('option', { name: 'M' }));

      expect(onSelectionChange).toHaveBeenCalledWith('m');
    });

    test('calls the hook select with the value of the clicked size item', async () => {
      const select = vi.fn();
      mockUseZimmSizeSelector.mockReturnValue(buildHookReturn({ select }));
      const values: SizeValue[] = [
        { value: 's', name: 'S', orderable: true },
        { value: 'm', name: 'M', orderable: true },
      ];

      render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute(values)}
          selectedValue={null}
          onSelectionChange={vi.fn()}
        />,
        { wrapper: Wrapper },
      );

      await userEvent.click(screen.getByRole('option', { name: 'S' }));

      expect(select).toHaveBeenCalledWith('s');
    });
  });

  describe('handleItemSelect — notify-me side effect', () => {
    // handleItemSelect is passed to ZimmDropdown as onItemSelect (the real component's own
    // Enter/Space keyboard handling calls this directly) AND wrapped inside each item's onClick
    // (mouse/pointer). Both input modalities call this exact same function, so exercising it via
    // a click proves the keyboard path fires identically — there is no separate keyboard-only
    // code path left to regress independently.
    test('calls onNotifyMeClick with the item value when the selected item is not orderable and the product is backorderable', async () => {
      const onNotifyMeClick = vi.fn();
      const onSelectionChange = vi.fn();
      const values: SizeValue[] = [
        { value: 's', name: 'S', orderable: true },
        { value: 'm', name: 'M', orderable: false },
      ];

      render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute(values)}
          selectedValue={null}
          onSelectionChange={onSelectionChange}
          isBackorderable={true}
          onNotifyMeClick={onNotifyMeClick}
        />,
        { wrapper: Wrapper },
      );

      await userEvent.click(screen.getByRole('option', { name: 'M' }));

      expect(onSelectionChange).toHaveBeenCalledWith('m');
      expect(onNotifyMeClick).toHaveBeenCalledWith('m');
    });

    test('does not call onNotifyMeClick for an orderable (in-stock) item', async () => {
      const onNotifyMeClick = vi.fn();
      const values: SizeValue[] = [
        { value: 's', name: 'S', orderable: true },
        { value: 'm', name: 'M', orderable: true },
      ];

      render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute(values)}
          selectedValue={null}
          onSelectionChange={vi.fn()}
          isBackorderable={true}
          onNotifyMeClick={onNotifyMeClick}
        />,
        { wrapper: Wrapper },
      );

      await userEvent.click(screen.getByRole('option', { name: 'M' }));

      expect(onNotifyMeClick).not.toHaveBeenCalled();
    });

    test('does not call onNotifyMeClick for an unorderable item when the product is not backorderable (out-of-stock, not notify-me)', async () => {
      const onNotifyMeClick = vi.fn();
      const values: SizeValue[] = [
        { value: 's', name: 'S', orderable: true },
        { value: 'm', name: 'M', orderable: false },
      ];

      render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute(values)}
          selectedValue={null}
          onSelectionChange={vi.fn()}
          isBackorderable={false}
          onNotifyMeClick={onNotifyMeClick}
        />,
        { wrapper: Wrapper },
      );

      await userEvent.click(screen.getByRole('option', { name: 'M' }));

      expect(onNotifyMeClick).not.toHaveBeenCalled();
    });
  });

  describe('multi-size branch', () => {
    test('renders ZimmDropdown and not the one-size paragraph when there are multiple values', () => {
      render(
        <ZimmSizeSelector
          variationAttribute={buildVariationAttribute()}
          selectedValue={null}
          onSelectionChange={vi.fn()}
        />,
        { wrapper: Wrapper },
      );

      expect(screen.getByTestId('zimm-dropdown')).toBeInTheDocument();
      expect(screen.queryByRole('status')).not.toBeInTheDocument();
    });
  });
});

