import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React, { useState } from 'react';
import { expect, userEvent, within } from 'storybook/test';
import { MultiSiteProvider } from '@salesforce/retail-react-app/app/contexts';
import { ZimmSizeSelector } from '.';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';

// ---------------------------------------------------------------------------
// Story utilities
// ---------------------------------------------------------------------------

/** Gives the in-flow panel room without clipping. */
const withRoom = (minHeight: string) => {
  const WithRoom = (Story: React.ComponentType) => (
    <div style={{ minHeight }}>
      <Story />
    </div>
  );
  WithRoom.displayName = 'WithRoom';
  return WithRoom;
};

const openPanel = async (canvasElement: HTMLElement) => {
  const canvas = within(canvasElement);
  await userEvent.click(canvas.getByRole('button', { name: 'Size' }));
  return canvas;
};

type StoryVariationAttribute = React.ComponentProps<typeof ZimmSizeSelector>['variationAttribute'];

const sizeAttribute = (values: StoryVariationAttribute['values']): StoryVariationAttribute => ({
  id: 'size',
  name: 'Size',
  values,
});

// ---------------------------------------------------------------------------
// Meta
// ---------------------------------------------------------------------------

const meta: Meta<typeof ZimmSizeSelector> = {
  title: 'Commerce/ZimmSizeSelector',
  component: ZimmSizeSelector,
  parameters: { layout: 'padded' },
  // The "Find your size"/"Size Guide" links render through ZimmNavItem, which now calls
  // useMultiSite() unconditionally (regional link prefixing fix) — same provider shape
  // drawer-menu/index.stories.tsx uses for this hook. No internal href is ever passed here
  // (ZimmSizeSelector's ZimmNavItem usages are onClick-only), so no MemoryRouter is needed,
  // just the provider so the hook call itself doesn't throw with no MultiSiteProvider mounted.
  decorators: [
    (Story) => (
      <MultiSiteProvider
        site={{ id: 'ZimmermannAU', alias: 'au' }}
        locale={{ id: 'en-AU', alias: 'en-AU' }}
        buildUrl={(path: string) => path}
      >
        <Story />
      </MultiSiteProvider>
    ),
  ],
};

export default meta;

type Story = StoryObj<typeof ZimmSizeSelector>;

// ---------------------------------------------------------------------------
// Stateless snapshot stories (CI play assertions)
// ---------------------------------------------------------------------------

/** AC 1 — default / unselected / closed. */
export const Default: Story = {
  args: {
    variationAttribute: sizeAttribute([
      { value: '4', name: '0', orderable: true },
      { value: '6', name: '2', orderable: true },
      { value: '8', name: '4', orderable: true },
      { value: '10', name: '6', orderable: true },
      { value: '12', name: '8', orderable: true },
      { value: '14', name: '10', orderable: true },
    ]),
    selectedValue: null,
    onSelectionChange: () => {},
  },
};

/** AC 2 — trigger shows the selected size. */
export const FilledWithSize: Story = {
  args: {
    variationAttribute: sizeAttribute([
      { value: '4', name: '0', orderable: true },
      { value: '6', name: '2', orderable: true },
      { value: '8', name: '4', orderable: true },
      { value: '10', name: '6', orderable: true },
      { value: '12', name: '8', orderable: true },
      { value: '14', name: '10', orderable: true },
    ]),
    selectedValue: '4',
    onSelectionChange: () => {},
  },
};

/** AC 3 — panel open, listbox present. */
export const Open: Story = {
  args: {
    variationAttribute: sizeAttribute([
      { value: '4', name: '0', orderable: true },
      { value: '6', name: '2', orderable: true },
      { value: '8', name: '4', orderable: true },
      { value: '10', name: '6', orderable: true },
      { value: '12', name: '8', orderable: true },
      { value: '14', name: '10', orderable: true },
    ]),
    selectedValue: null,
    onSelectionChange: () => {},
  },
  decorators: [withRoom('320px')],
  play: async ({ canvasElement }) => {
    const canvas = await openPanel(canvasElement);
    await expect(canvas.getByRole('listbox')).toBeInTheDocument();
  },
};

/** showError — "Size required" announced via role="alert". */
export const ErrorState: Story = {
  args: {
    variationAttribute: sizeAttribute([
      { value: '4', name: '0', orderable: true },
      { value: '6', name: '2', orderable: true },
      { value: '8', name: '4', orderable: true },
      { value: '10', name: '6', orderable: true },
      { value: '12', name: '8', orderable: true },
      { value: '14', name: '10', orderable: true },
    ]),
    selectedValue: null,
    onSelectionChange: () => {},
    showError: true,
  },
};

/** AC 4 / 5 / 6 — orderable and out-of-stock sizes visible simultaneously. */
export const AllStatuses: Story = {
  args: {
    variationAttribute: sizeAttribute([
      { value: '4', name: '0', orderable: true },
      { value: '6', name: '2', orderable: true },
      { value: '8', name: '4', orderable: true },
      { value: '10', name: '6', orderable: false },
      { value: '12', name: '8', orderable: true },
      { value: '14', name: '10', orderable: false },
    ]),
    selectedValue: null,
    onSelectionChange: () => {},
    isBackorderable: false,
  },
  decorators: [withRoom('440px')],
};

/** AC 7 — unorderable sizes become "Notify Me" on a backorderable product. */
export const Backorderable: Story = {
  args: {
    variationAttribute: sizeAttribute([
      { value: '4', name: '0', orderable: true },
      { value: '6', name: '2', orderable: true },
      { value: '8', name: '4', orderable: true },
      { value: '10', name: '6', orderable: false },
      { value: '12', name: '8', orderable: true },
      { value: '14', name: '10', orderable: false },
    ]),
    selectedValue: null,
    onSelectionChange: () => {},
    isBackorderable: true,
  },
  decorators: [withRoom('440px')],
  play: async ({ canvasElement }) => {
    const canvas = await openPanel(canvasElement);
    // Notify Me badge is a <span> inside role="option", not a standalone button.
    await expect(canvas.getAllByRole('option', { name: /Notify Me/i })).toHaveLength(2);
  },
};

/** AC 10 / 11 — one-size: no dropdown, no link, auto-selected on mount. */
export const OneSize: Story = {
  args: {
    variationAttribute: sizeAttribute([{ value: 'os', name: 'One size', orderable: true }]),
    selectedValue: null,
    onSelectionChange: () => {},
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByRole('status')).toHaveTextContent('One size');
    await expect(canvas.queryByRole('button')).not.toBeInTheDocument();
  },
};

/** A3 — Space key selects the focused row and closes the panel. */
export const KeyboardSelection: Story = {
  args: {
    variationAttribute: sizeAttribute([
      { value: '4', name: '0', orderable: true },
      { value: '6', name: '2', orderable: true },
      { value: '8', name: '4', orderable: true },
      { value: '10', name: '6', orderable: true },
      { value: '12', name: '8', orderable: true },
      { value: '14', name: '10', orderable: true },
    ]),
    selectedValue: null,
    onSelectionChange: () => {},
  },
  decorators: [withRoom('320px')],
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const trigger = canvas.getByRole('button', { name: 'Size' });
    await userEvent.click(trigger);
    await userEvent.keyboard('{ArrowDown}');
    // ZimmDropdown moves real DOM focus to the option element (not aria-activedescendant
    // on the trigger) — verify the first option has received focus.
    await expect(canvas.getAllByRole('option')[0]).toHaveFocus();
    await userEvent.keyboard(' ');
    await expect(canvas.queryByRole('listbox')).not.toBeInTheDocument();
  },
};

// ---------------------------------------------------------------------------
// Interactive stories — real state, for local browser QA against all ACs
// Named wrapper components are required so that useState is called at the
// top level of a React component, not inside a render callback.
// ---------------------------------------------------------------------------

type SizeSelectorArgs = React.ComponentProps<typeof ZimmSizeSelector>;

const InteractiveStory = (args: SizeSelectorArgs) => {
  const [selected, setSelected] = useState<string | null>(null);
  return <ZimmSizeSelector {...args} selectedValue={selected} onSelectionChange={setSelected} />;
};

const WithAddToBagStory = (args: SizeSelectorArgs) => {
  const [selected, setSelected] = useState<string | null>(null);
  const selectedEntry = args.variationAttribute.values.find((v) => v.value === selected);
  const isOOS = selected !== null && selectedEntry ? !selectedEntry.orderable : false;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--zimm-scale-700)' }}>
      <ZimmSizeSelector {...args} selectedValue={selected} onSelectionChange={setSelected} />
      <ZimmButton
        label="ADD TO BAG"
        variant="primary"
        fullWidth={true}
        disabled={false}
        ariaDisabled={isOOS}
        onClick={() => {
          window.alert(`Added size ${selectedEntry?.name ?? '?'} to bag`);
        }}
      />
    </div>
  );
};

const OneSizeWithAddToBagStory = (args: SizeSelectorArgs) => {
  const [selected, setSelected] = useState<string | null>(null);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--zimm-scale-700)' }}>
      <ZimmSizeSelector {...args} selectedValue={selected} onSelectionChange={setSelected} />
      <ZimmButton
        label="ADD TO BAG"
        variant="primary"
        fullWidth={true}
        disabled={false}
        ariaDisabled={selected === null}
        onClick={() => {
          window.alert('Added one-size item to bag');
        }}
      />
    </div>
  );
};

/**
 * Fully interactive — selection updates the trigger. Use this to manually
 * verify AC 1–9 (except mobile) in the browser.
 */
export const Interactive: Story = {
  render: (args) => <InteractiveStory {...args} />,
  args: {
    variationAttribute: sizeAttribute([
      { value: '4', name: '0', orderable: true },
      { value: '6', name: '2', orderable: true },
      { value: '8', name: '4', orderable: true },
      { value: '10', name: '6', orderable: false },
      { value: '12', name: '8', orderable: true },
      { value: '14', name: '10', orderable: false },
    ]),
    isBackorderable: false,
  },
  decorators: [withRoom('440px')],
};

/**
 * AC 6 — OOS size selected → Add to Bag becomes aria-disabled (reachable by keyboard/SR).
 * AC 7 — switch isBackorderable to true in Storybook controls to see Notify Me rows.
 *
 * Interaction:
 *   1. Select any in-stock size → button is active.
 *   2. Select an OOS row → button turns visually disabled but stays focusable.
 *   3. Click the disabled button → no action fires (aria-disabled suppresses onClick).
 */
export const WithAddToBag: Story = {
  render: (args) => <WithAddToBagStory {...args} />,
  args: {
    variationAttribute: sizeAttribute([
      { value: '4', name: '0', orderable: true },
      { value: '6', name: '2', orderable: true },
      { value: '8', name: '4', orderable: true },
      { value: '10', name: '6', orderable: false },
      { value: '12', name: '8', orderable: true },
      { value: '14', name: '10', orderable: false },
    ]),
    isBackorderable: false,
  },
  decorators: [withRoom('440px')],
};

/**
 * AC 6 + 7 — backorderable variant of WithAddToBag: OOS rows show "Notify Me"
 * but still disable Add to Bag when selected.
 */
export const WithAddToBagBackorderable: Story = {
  render: (args) => <WithAddToBagStory {...args} />,
  args: {
    variationAttribute: sizeAttribute([
      { value: '4', name: '0', orderable: true },
      { value: '6', name: '2', orderable: true },
      { value: '8', name: '4', orderable: true },
      { value: '10', name: '6', orderable: false },
      { value: '12', name: '8', orderable: true },
      { value: '14', name: '10', orderable: false },
    ]),
    isBackorderable: true,
  },
  decorators: [withRoom('440px')],
};

/**
 * AC 10 / 11 interactive — one-size auto-selects on mount. Add to Bag should be active
 * immediately with no shopper interaction.
 */
export const OneSizeWithAddToBag: Story = {
  render: (args) => <OneSizeWithAddToBagStory {...args} />,
  args: {
    variationAttribute: sizeAttribute([{ value: 'os', name: 'One size', orderable: true }]),
  },
