71	  'padding',
72	  'margin',
73	  'gap',
74	  'inset',
75	  'p',
76	  'm',
77	  'px',
78	  'py',
79	  'mx',
80	  'my',
81	  'pt',
82	  'pb',
83	  'pl',
84	  'pr',
