import React, { useEffect, useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmSizeChip } from '../../atoms/zimmSizeChip';

const messages = defineMessages({
  groupLabel: { id: 'size_chips.group.label', defaultMessage: 'Select a size' },
});

const ZIMM_SIZE_CHIP_GROUP_RECIPE = 'ZimmSizeChipGroup';

/** One selectable size as the molecule expects it — pre-mapped from the raw SFCC shape. */
export type ZimmSizeChipValue = {
  value: string;
  label: string;
  /**
   * Mirrors SFCC's orderable/stock flag for this size. Unlike ZimmColourSwatchGroup's colours
   * (withheld entirely when unavailable), an unavailable size is shown disabled so the shopper
   * can still see the full size run — the size-chip Figma component set includes a dedicated
   * Disabled state for exactly this.
   */
  isDisabled?: boolean;
};

type ZimmSizeChipGroupProps = {
  values: ZimmSizeChipValue[];
  /** Currently selected size value (from URL / variation params). */
  selectedValue?: string;
  /**
   * Selection callback. Called on click and on arrow-key navigation landing on a new chip.
   * Never called for a disabled size under any input method.
   */
  onSelect?: (value: string) => void;
};

/** Index of the first non-disabled entry in `list`, or -1 when every entry is disabled. */
const firstEnabledIndex = (list: ZimmSizeChipValue[]): number => list.findIndex((v) => !v.isDisabled);

/**
 * The roving-tabindex/selection target: the selected value's index when it is itself enabled,
 * else the first enabled entry. Kept as a standalone pure function (rather than a closure over
 * component props) so the effect below can list its real inputs (`list`, `selected`) directly
 * as dependencies, with nothing left out for eslint's exhaustive-deps to flag.
 */
const computeFocusIndex = (list: ZimmSizeChipValue[], selected: string | undefined): number => {
  const selectedIndex = list.findIndex((v) => v.value === selected);
  return selectedIndex >= 0 && !list[selectedIndex].isDisabled ? selectedIndex : firstEnabledIndex(list);
};

/**
 * Molecule — the full PDP size-chip group: a `[role=radiogroup]` row of ZimmSizeChip atoms with
 * roving tabindex and keyboard navigation, adapted from ZimmColourSwatchGroup's
 * handleSwatchesKeyDown for a row with no pagination and a real per-chip disabled state (arrow
 * navigation must skip a disabled chip rather than land on or select it).
 *
 * When exactly one size is offered, the size-chip Figma component set's other Type applies: a
 * single non-interactive label renders instead of a one-item radiogroup — a genuinely
 * different, non-interactive component, not a radiogroup with one item.
 */
export const ZimmSizeChipGroup = ({ values, selectedValue, onSelect }: ZimmSizeChipGroupProps) => {
  const intl = useIntl();
  const groupLabel = intl.formatMessage(messages.groupLabel);
  const styles = useMultiStyleConfig(ZIMM_SIZE_CHIP_GROUP_RECIPE, {});

  // Roving-tabindex target, tracked as its own state rather than derived fresh every render —
  // arrow-key navigation updates it directly so the tab stop (and the imperative focus below)
  // moves within a single interaction, without depending on a controlling parent re-passing a
  // new `selectedValue` prop first.
  const [focusIndex, setFocusIndex] = useState(() => computeFocusIndex(values, selectedValue));

  // Re-sync the roving tab stop whenever the selected value or the list itself changes from
  // outside this component (e.g. a controlling page changing colour, which can change which
  // sizes are disabled).
  useEffect(() => {
    setFocusIndex(computeFocusIndex(values, selectedValue));
  }, [values, selectedValue]);

  const radiogroupRef = useRef<HTMLDivElement>(null);
  const shouldRefocus = useRef(false);

  // Imperative focus after arrow-key navigation — mirrors ZimmColourSwatchGroup's own
  // hasNavigated-ref pattern, adapted to fire off this component's own focusIndex state
  // directly rather than waiting on a selectedValue round-trip through a controlling parent.
  useEffect(() => {
    if (!shouldRefocus.current) return;
    shouldRefocus.current = false;
    const target = values[focusIndex];
    if (!target) return;
    const el = radiogroupRef.current?.querySelector(`[data-size-value="${target.value}"]`);
    (el as HTMLElement | null)?.focus();
  }, [focusIndex, values]);

  const selectIndex = (index: number, { refocus }: { refocus: boolean }) => {
    const target = values[index];
    if (!target || target.isDisabled) return;
    setFocusIndex(index);
    shouldRefocus.current = refocus;
    onSelect?.(target.value);
  };

  const handleChipsKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
    e.preventDefault();
    if (values.length === 0) return;

    // Derive current index from the focused element's data-size-value — a unique value
    // identity that survives duplicate display labels, same reasoning as
    // zimmColourSwatchGroup's own data-swatch-value lookup.
    const focusedValue = (document.activeElement as HTMLElement | null)?.getAttribute('data-size-value');
    const focusedIndex = focusedValue ? values.findIndex((v) => v.value === focusedValue) : -1;
    const currentIndex = focusedIndex >= 0 ? focusedIndex : focusIndex;
    if (currentIndex < 0) return; // every chip disabled — nothing to navigate from

    const step = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1;

    let nextIndex = currentIndex;
    for (let attempt = 0; attempt < values.length; attempt += 1) {
      nextIndex = (nextIndex + step + values.length) % values.length;
      if (!values[nextIndex].isDisabled) {
        selectIndex(nextIndex, { refocus: true });
        return;
      }
    }
    // Looped through every chip and found none enabled — nothing to do.
  };

  // Nothing offered — suppress the group entirely rather than render an empty radiogroup, same
  // "nothing to show" precedent as zimmColourSwatchGroup's own offered.length === 0 guard.
  if (values.length === 0) return null;

  if (values.length === 1) {
    return (
      <chakra.span __css={styles.oneSize} data-testid="size-chip-one-size">
        {values[0].label}
      </chakra.span>
    );
  }

  return (
    <chakra.div
      role="radiogroup"
      aria-label={groupLabel}
      ref={radiogroupRef}
      __css={styles.radiogroup}
      onKeyDown={handleChipsKeyDown}
    >
      {values.map((v, i) => (
        <ZimmSizeChip
          key={v.value}
          value={v.value}
          label={v.label}
          isSelected={v.value === selectedValue}
          isDisabled={v.isDisabled}
          isFocusable={i === focusIndex}
          onSelect={() => selectIndex(i, { refocus: false })}
        />
      ))}
    </chakra.div>
  );
};

export default ZimmSizeChipGroup;

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the PDP size-chip group. Two mutually-exclusive root renders, matching the two
 * "Type" variants of the size-chip Figma component set (node 40003066:34868):
 *   - `radiogroup` — the multi-size row (the default Type, 208x28 in Figma) — lays out
 *     ZimmSizeChip atoms in a row; each chip's own fill/border/focus styling stays in the
 *     sibling ZimmSizeChip atom's own recipe, this part is layout only.
 *   - `oneSize` — the single non-interactive label shown when only one size is offered (the
 *     other Type, 65x28 in Figma) — a genuinely different, non-interactive component, not a
 *     radiogroup with one item. Renders as a bordered box, the same visual language as the
 *     real interactive chips, just non-interactive — confirmed via `get_design_context` on
 *     node 40003066:34866 ("Type=One Size").
 */
export const ZimmSizeChipGroup = {
  parts: ['radiogroup', 'oneSize'],
  baseStyle: (): Record<string, SystemStyleObject> => ({
    radiogroup: {
      display: 'flex',
      alignItems: 'center',
      // `justifyContent: 'space-between'`, not a `gap` value: confirmed directly against the
      // real composed instance (`get_design_context` on node 40002163:41459, the PLP/PDP Hover
      // card) — the SizeSelector row is `flex items-center justify-between w-[208px]`, spreading
      // however many chips exist evenly across the card's full content width, with no gap
      // declared alongside it. This was previously left undeclared entirely ("no inter-chip gap
      // value confirmed") pending that exact measurement, which rendered every chip flush against
      // its neighbour with zero spacing — confirmed live (each 28px chip exactly 28px from the
      // next, i.e. touching) during the SFCC-236 Step 6 real-browser/Figma visual audit.
      justifyContent: 'space-between',
    },

    oneSize: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      // The non-interactive single-label footprint from the size-chip Figma component set's
      // other Type — no matching width-scale token for 65px; height reuses the same
      // --zimm-scale-700 (28px) the ZimmSizeChip atom's own `chip` part uses, since it is the
      // same row height as the interactive variant.
      // audit-allow: 65px — no foundation width token exists for this exact non-interactive
      // label size
      width: '65px',
      height: 'var(--zimm-scale-700)',
      // No token named for this specific "primary/dark border" purpose exists in the
      // `border` alias tier (see foundation/colour.ts) — only default/secondary/focus/
      // forms/error. The value here is confirmed directly against Figma node
      // 40003066:34866 ("Type=One Size") and matches `border.focus` (grey/900) exactly, but
      // the token name is semantically wrong for a static, non-focus box — the same
      // reuse-for-the-wrong-purpose gap already accepted in zimmSizeChip.css.ts's own
      // resolveBorderColour (Selected reuses border.focus to mean "selected") and
      // zimmSlideIndicator.css.ts's active dot. Pending a real foundation token from the
      // UI designer.
      border: 'var(--zimm-border-width-default) solid var(--zimm-color-border-focus)',
      // Figma's own citation for this text node is `size: default/caption`, not a button
      // style — matches this codebase's `caption` textStyle line for line (fontFamily/
      // fontSize/fontWeight/lineHeight/letterSpacing all identical to `buttonSm`) except
      // `caption` has no `textTransform`, correctly: this is a static label, not a button.
      textStyle: 'caption',
      color: 'var(--zimm-color-text-default)',
    },
  }),
};

import type { SystemStyleObject } from '@chakra-ui/react';

// Figma Textfield flush variant (node 40000265:374): field/border/* tokens.
// hover and filled (has value, unfocused) both darken to focus colour per Figma spec.
const BORDER = {
  default: 'var(--zimm-color-border-forms)', // #707070 — Figma field/border/default
  hover: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/hover
  filled: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/filled
  focus: 'var(--zimm-color-border-focus)', // #191919 — Figma field/border/focus
  error: 'var(--zimm-color-status-error)', // #9c0000 — Figma field/border/error
} as const;

// Figma field/border/inverse/default = white (opaque), inverse/error = #f98f8c (coral).
// Figma does not spec inverse/hover or inverse/focus separately — same white as default.
const BORDER_INVERSE = {
  default: 'var(--zimm-color-text-inverse)',
  hover: 'var(--zimm-color-text-inverse)',
  filled: 'var(--zimm-color-text-inverse)',
  focus: 'var(--zimm-color-text-inverse)',
  error: 'var(--zimm-color-status-error-bg)', // #f98f8c
} as const;

// Figma: Textfield flush floated label — brand/font/size/250 (10px) / medium weight.
const LABEL_FLOATED_SIZE = 'var(--zimm-font-size-4xs)';
const LABEL_FLOATED_WEIGHT = 'var(--zimm-font-weight-medium)';
// Figma: content div h-[36px] — pending alias/size/field/height token from the designer.
// rem, not px: this height participates in a rem-derived measurement, so it has to scale with the
// root font-size (WCAG 1.4.4 — see overrideStyling.md > Units). footer.css.ts's SIZE_SUBSCRIBE_SLOT
// analogue in zimmSubscribeSection.css.ts (2.8125rem) documents itself as "36px content + 4px/4px
// padding + 1px border"; freezing the content height in px broke that derivation as soon as the
// root font-size moved — at 200% zoom the slot reached 90px while the field reached only 53px,
// over-reserving by ~37px. (Dead space, not clipping — the no-layout-shift guarantee held either
// way.) In rem it holds at every zoom level. This file is now developer-owned per the co-location
// pattern (overrideStyling.md), but the value itself is still PROVISIONAL pending Kiera — this
// should ride along with that sign-off, not land silently.
const FIELD_CONTENT_HEIGHT = '2.25rem'; // 36px at the default 16px root
// No opacity token in foundation yet — pending Tier 1 PR with UI-designer sign-off.
const OPACITY_DISABLED = 0.4;

const MOTION = 'var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)';

/** State the component feeds in so the recipe can resolve the Figma colour cascade. */
export type ZimmTextInputStyleProps = {
  inverse?: boolean;
  disabled?: boolean;
  hasError?: boolean;
  focused?: boolean;
  /** Field has a value. Combined with `focused` this gives the floated-label state. */
  filled?: boolean;
  /** Render a full box-border (all four sides) instead of the default flush bottom-border only. */
  outlined?: boolean;
};

const palette = (inverse?: boolean) => (inverse ? BORDER_INVERSE : BORDER);

/** Border colour precedence: disabled > error > focus > filled > default. */
export const resolveBorderColour = ({ inverse, disabled, hasError, focused, filled }: ZimmTextInputStyleProps) => {
  const p = palette(inverse);
  if (disabled) return p.default;
  if (hasError) return p.error;
  if (focused) return p.focus;
  if (filled) return p.filled;
  return p.default;
};

/** In error the hover colour holds (error > hover); otherwise it darkens to focus. */
export const resolveHoverBorderColour = (props: ZimmTextInputStyleProps) =>
  props.hasError ? resolveBorderColour(props) : palette(props.inverse).hover;

// Figma text/subtle = #666 for the floated/disabled label in light mode;
// text/inverse/subtle = #969696 in inverse mode.
export const resolveLabelColour = ({ inverse, disabled, focused, filled }: ZimmTextInputStyleProps) => {
  const floated = Boolean(focused || filled);
  if (disabled) return inverse ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-secondary)';
  if (inverse) return floated ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-inverse)';
  return floated ? 'var(--zimm-color-text-secondary)' : 'var(--zimm-color-text-default)';
};

export const ZimmTextInput = {
  parts: ['root', 'row', 'content', 'label', 'input', 'clearButton', 'helper', 'error'],
  baseStyle: (props: ZimmTextInputStyleProps): Record<string, SystemStyleObject> => {
    const { inverse, disabled, focused, filled } = props;
    const floated = Boolean(focused || filled);
    const textColour = inverse ? 'var(--zimm-color-text-inverse)' : 'var(--zimm-color-text-default)';

    const { outlined } = props;
    const borderDecl = `var(--zimm-border-width-default) solid ${resolveBorderColour(props)}`;

    return {
      root: {
        display: 'block',
        width: '100%',
        opacity: disabled ? OPACITY_DISABLED : 1,
      },

      // Flush bottom-border row (default) or full box-border when `outlined` is true.
      // Hover is a CSS pseudo-class, not JS state.
      row: {
        display: 'flex',
        alignItems: 'center',
        gap: 'var(--zimm-scale-xs)',
        ...(outlined
          ? {
              border: borderDecl,
              // SFCC-926 (Figma): outlined variant padding is 4px 12px — was incorrectly
              // set to 8px inline; corrected to --zimm-scale-s (12px) per Figma spec.
              paddingTop: 'var(--zimm-scale-2xs)',
              paddingBottom: 'var(--zimm-scale-2xs)',
              paddingInline: 'var(--zimm-scale-s)',
            }
          : {
              borderBottom: borderDecl,
              paddingTop: 'var(--zimm-scale-2xs)',
              paddingBottom: 'var(--zimm-scale-2xs)',
            }),
        // not in Figma — UX animation on border-colour state changes
        transition: `border-color ${MOTION}`,
        _hover: disabled
          ? undefined
          : outlined
            ? { borderColor: resolveHoverBorderColour(props) }
            : { borderBottomColor: resolveHoverBorderColour(props) },
      },

      // Figma: content flex-[1_0_0] h-[36px]
      content: { flex: 1, position: 'relative', minHeight: FIELD_CONTENT_HEIGHT },

      label: {
        position: 'absolute',
        left: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontWeight: floated ? LABEL_FLOATED_WEIGHT : 'var(--zimm-font-weight-regular)',
        fontSize: floated ? LABEL_FLOATED_SIZE : 'var(--zimm-font-size-2xs)',
        lineHeight: floated ? undefined : 'var(--zimm-font-lineheight-2xs)',
        color: resolveLabelColour(props),
        top: floated ? 'var(--zimm-scale-3xs)' : '50%',
        transform: floated ? 'none' : 'translateY(-50%)',
        transition: `top ${MOTION}, transform ${MOTION}, font-size ${MOTION}, color ${MOTION}`,
        whiteSpace: 'nowrap',
      },

      input: {
        position: 'absolute',
        bottom: 0,
        left: 0,
        right: 0,
        width: '100%',
        height: 'var(--zimm-scale-l)', // 20px — var, not 'l': theme.sizes has no 'l' key
        background: 'transparent',
        border: 'none',
        outline: 'none',
        fontFamily: 'var(--zimm-font-family-body)',
        fontWeight: 'var(--zimm-font-weight-regular)',
        fontSize: 'var(--zimm-font-size-2xs)',
        color: textColour,
        padding: 0,
        opacity: floated ? 1 : 0,
        cursor: disabled ? 'not-allowed' : 'text',
        transition: `opacity ${MOTION}`,
      },

      clearButton: {
        background: 'transparent',
        border: 'none',
        padding: 0,
        cursor: 'pointer',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        flexShrink: 0,
        color: textColour,
        // WCAG 2.2 AA SC 2.5.8 — 24px minimum target size
        // var, not 'xl': min-width/height resolve via theme.sizes (xl = 36rem), not theme.space
        minWidth: 'var(--zimm-scale-xl)',
        minHeight: 'var(--zimm-scale-xl)',
        // WCAG 2.2 AA SC 2.4.7 — visible focus state
        _focusVisible: {
          outline: inverse
            ? 'var(--zimm-border-width-default) solid var(--zimm-color-text-inverse)'
            : 'var(--zimm-focus-ring)',
          outlineOffset: 'var(--zimm-focus-ring-offset-default)',
          boxShadow: 'none',
        },
      },

      helper: {
        marginTop: 'var(--zimm-scale-2xs)',
        marginBottom: 0,
        marginInline: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontSize: 'var(--zimm-font-size-3xs)',
        color: inverse ? 'var(--zimm-color-text-inverse-grey)' : 'var(--zimm-color-text-secondary)',
      },

      error: {
        marginTop: 'var(--zimm-scale-2xs)',
        marginBottom: 0,
        marginInline: 0,
        fontFamily: 'var(--zimm-font-family-body)',
        fontSize: 'var(--zimm-font-size-2xs)',
        fontStyle: 'normal',
        fontWeight: 'var(--zimm-font-weight-regular)',
        lineHeight: 'var(--zimm-font-lineheight-2xs)',
        color: inverse ? 'var(--zimm-color-status-error-bg)' : 'var(--zimm-color-status-error)',
      },
    };
  },
};

import { FONT_MEDIUM, FONT_REGULAR, FONT_SERIF } from './fonts';

// Typography scale primitives — deduplicated from the 22 Handover text styles below.
// zimmTokens.ts's --zimm-font-size-*/lineheight-*/letterspacing-* entries read from
// here too. Naming matches those --zimm-* suffixes.
export const fontSizes = {
  md: '1.5rem', // 24px
  xs: '1rem', // 16px
  '2xs': '0.875rem', // 14px
  '3xs': '0.75rem', // 12px
  '4xs': '0.625rem', // 10px
} as const;

export const lineHeights = {
  md: '2rem', // 32px
  xs: '1.5rem', // 24px
  '2xs': '1.125rem', // 18px
  '3xs': '1rem', // 16px
  '4xs': '0.875rem', // 14px
} as const;

export const letterSpacings = {
  sm: '0',
  xs: '-0.0075rem', // -0.12px
  // Only used by linkLg — still a named token rather than a raw literal so it can't
  // drift out of sync with globalStyles.ts's zimmTextLinkLg.
  '2xs': '-0.00875rem', // -0.14px
  footer: '0.025rem', // 0.4px
} as const;

export const fontWeights = {
  medium: '500',
  regular: '400',
} as const;

// Named text styles — source: Zimmermann Design System 2026 (Handover tokens/typography.css)
// Token name → fontFamily / fontWeight / fontSize / lineHeight / letterSpacing / transform
export const textStyles = {
  // ---- Headings ----
  // ZIM/h1-strong (.zimm-text-h1-strong): 500 weight, uppercase
  heading1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.md,
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/h1 (.zimm-text-h1): 400 weight, uppercase
  heading1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights.md,
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/h2-strong (.zimm-text-h2-strong)
  heading2: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.sm,
  },
  // ZIM/h3-strong (.zimm-text-h3-strong)
  heading3: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
    textTransform: 'uppercase' as const,
  },
  // ---- Body ----
  // ZIM/body1-strong (.zimm-text-body1-strong)
  body1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body1 (.zimm-text-body1)
  body1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body2-strong (.zimm-text-body2-strong)
  body2Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body2 (.zimm-text-body2)
  body2: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Mobile body ----
  // ZIM/Mobile/Body1-strong (.zimm-text-mobile-body1-strong)
  mobileBody1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
